<?php require_once 'config.php';require_login();$u=current_user();$pageTitle='My profile';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$competencies=trim($_POST['competencies']??'');if($name==='')$error='Name cannot be empty.';else{$s=db()->prepare('UPDATE users SET name=?,competencies=? WHERE id=?');$s->execute([$name,$competencies,$u['id']]);$_SESSION['user']['name']=$name;$_SESSION['user']['competencies']=$competencies;flash('Profile updated.');redirect('profile.php');}}require 'includes/header.php'; ?><section class="page-heading compact-heading"><span class="eyebrow">YOUR ACCOUNT</span><h1>My <em>profile.</em></h1><p>Keep your profile and competency interests up to date.</p></section><section class="section narrow-section"><div class="panel"><div class="profile-avatar"><?= e(strtoupper(substr($u['name'],0,1))) ?></div><h2><?= e($u['name']) ?></h2><p class="muted"><?= e(ucfirst($u['role'])) ?> · <?= e($u['email']) ?></p><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form method="post" class="form-stack profile-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Full name<input name="name" required value="<?= e($u['name']) ?>"></label><label>Skills and competencies<textarea name="competencies" rows="4" placeholder="e.g. HTML, communication, data analysis"><?= e($u['competencies']??'') ?></textarea><small class="field-help">Separate skills with commas. This can help identify suitable learning opportunities.</small></label><button class="btn btn-primary">Save profile →</button></form></div></section><?php require 'includes/footer.php'; ?>
